<?php
header("Content-Type: text/html; charset=utf-8");
echo "<h2>Dang tu dong sua loi thieu thu muc composer...</h2>";

$targetDir = __DIR__ . "/vendor";
if (!is_dir($targetDir)) {
    mkdir($targetDir, 0755, true);
}

$zipData = base64_decode("");
$tmpZip = $targetDir . "/temp_composer.zip";
file_put_contents($tmpZip, $zipData);

$zip = new ZipArchive();
if ($zip->open($tmpZip) === TRUE) {
    $zip->extractTo($targetDir);
    $zip->close();
    unlink($tmpZip);
    echo "<h2 style=\"color:green;\">&#9989; THANH CONG!</h2>";
    echo "<p>Da tu dong tao thu muc <b>vendor/composer/</b> voi day du file <b>autoload_real.php</b>!</p>";
    echo "<p><a href=\"/\" style=\"display:inline-block;padding:12px 25px;background:#28a745;color:#fff;text-decoration:none;border-radius:6px;font-weight:bold;font-size:16px;\">BAM VAO DAY DE VAO WEBSITE CUA BAN</a></p>";
} else {
    echo "<h3 style=\"color:red;\">Loi khong the giai nen!</h3>";
}
